using UnityEngine;using UnityEditor;using System.Linq;using System.Text;
public static class ProbeEntrance{public static string Main(){var sb=new StringBuilder();var t=Terrain.activeTerrain;var m=Object.FindFirstObjectByType<TrikeController>().GetComponent<MotorollerController>();using var so=new SerializedObject(m);var c=Vector3.Scale(so.FindProperty("collisionCenter").vector3Value,m.transform.lossyScale);var e=Vector3.Scale(so.FindProperty("collisionHalfExtents").vector3Value,m.transform.lossyScale);
foreach(var col in Physics.OverlapBox(new Vector3(46,10,129),new Vector3(12,5,12)).Where(c=>!(c is TerrainCollider)))sb.AppendLine(col.name+" "+col.GetType().Name+" "+col.bounds);
int bad=0;for(float z=124;z<=134;z+=1)for(float x=40;x<=50;x+=1){var p=new Vector3(x,0,z);p.y=t.SampleHeight(p)+t.transform.position.y+.02f;var q=Quaternion.LookRotation(Vector3.left);foreach(var h in Physics.BoxCastAll(p+q*c,e,Vector3.left,q,.225f,~0,QueryTriggerInteraction.Ignore).Where(h=>h.normal.y<=.65f&&(!(h.collider is TerrainCollider)||h.distance>0))){if(bad++<35)sb.AppendLine(p+" hits "+h.collider.name+" d="+h.distance+" normal="+h.normal+" point="+h.point);}}
return sb.ToString();}}
